const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Washington state geometry
  const washington = ee.FeatureCollection('TIGER/2018/States')
    .filter(ee.Filter.eq('NAME', 'Washington'))
    .geometry();

  // 2. Define dates
  const date1 = '2021-11-15';
  const date2 = '2021-11-22';

  // 3. Load SMAP soil moisture data
  const smap = ee.ImageCollection('NASA_USDA/HSL/SMAP10KM_soil_moisture');

  // Get images for both dates (SMAP updates every ~3 days, so use 3-day window)
  const img1 = smap
    .filterDate(date1, ee.Date(date1).advance(3, 'day'))
    .filterBounds(washington)
    .select('ssm')
    .mean();

  const img2 = smap
    .filterDate(date2, ee.Date(date2).advance(3, 'day'))
    .filterBounds(washington)
    .select('ssm')
    .mean();

  // Check if collections have data
  const col1 = smap.filterDate(date1, ee.Date(date1).advance(3, 'day')).filterBounds(washington);
  const col2 = smap.filterDate(date2, ee.Date(date2).advance(3, 'day')).filterBounds(washington);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Nov 15 images: ${size1}`);
  console.log(`Nov 22 images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('No data for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 4. Calculate mean soil moisture and pixel counts
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: washington,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const moisture1 = stats1.ssm_mean;
  const count1 = stats1.ssm_count;
  const moisture2 = stats2.ssm_mean;
  const count2 = stats2.ssm_count;

  console.log(`Nov 15: Moisture=${moisture1?.toFixed(4)}, Pixels=${count1}`);
  console.log(`Nov 22: Moisture=${moisture2?.toFixed(4)}, Pixels=${count2}`);

  // 5. Validation and answer
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (moisture1 == null || moisture2 == null || isNaN(moisture1) || isNaN(moisture2)) {
    console.log('Calculation failed - invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (moisture1 < 0 || moisture1 > 1 || moisture2 < 0 || moisture2 > 1) {
    console.log('Invalid soil moisture range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare moisture levels
  if (moisture2 > moisture1) {
    console.log('Nov 22 was more moist than Nov 15.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Nov 22 was not more moist than Nov 15.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
